        category: "Accessories",
        price: 120.00,
        originalPrice: null,
        image: "https://images.unsplash.com/photo-1553062407-98eeb64c6a62?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=80",
        badge: "Bestseller"
    }
];

// DOM Elements
const productGrid = document.getElementById('product-grid');
const cartCount = document.querySelector('.cart-count');
const mobileMenuBtn = document.querySelector('.mobile-menu-btn');
const navList = document.getElementById('nav-list');
const currentYearSpan = document.getElementById('current-year');
const announcer = document.getElementById('announcer');

// State
let cartQuantity = 0;

// Initialize App
function init() {
    renderProducts();
    setCurrentYear();
    setupEventListeners();
}

// Render Products
function renderProducts() {
    if (!productGrid) return;

    productGrid.innerHTML = '';

    products.forEach(product => {
        const article = document.createElement('article');
        article.className = 'product-card';

        let badgeHtml = '';
        if (product.badge) {
            badgeHtml = `<span class="product-badge">${product.badge}</span>`;
        }

        let priceHtml = `<span class="product-price">$${product.price.toFixed(2)}</span>`;
        if (product.originalPrice) {
            priceHtml = `
                <span class="original-price sr-only">Original price:</span>
                <span class="original-price">$${product.originalPrice.toFixed(2)}</span>
                <span class="product-price sr-only">Sale price:</span>
                <span class="product-price">$${product.price.toFixed(2)}</span>
            `;
        }

        article.innerHTML = `
            ${badgeHtml}
            <div class="product-image">
                <img src="${product.image}" alt="${product.name}" loading="lazy">
            </div>
            <div class="product-info">
                <div class="product-category">${product.category}</div>
                <h3 class="product-title">
                    <a href="#product-${product.id}">${product.name}</a>
                </h3>
                <div class="price-container">
                    ${priceHtml}
                </div>
                <button class="add-to-cart-btn" data-id="${product.id}" aria-label="Add ${product.name} to cart">
                    Add to Cart
                </button>
            </div>
        `;

        productGrid.appendChild(article);
    });
}

// Event Listeners
function setupEventListeners() {
    // Mobile Menu Toggle
    if (mobileMenuBtn && navList) {
        mobileMenuBtn.addEventListener('click', () => {
            const isExpanded = mobileMenuBtn.getAttribute('aria-expanded') === 'true';
            mobileMenuBtn.setAttribute('aria-expanded', !isExpanded);
            navList.classList.toggle('active');

            // Announce menu state to screen readers
            announce(isExpanded ? 'Navigation menu closed' : 'Navigation menu opened');
        });
    }

    // Add to Cart Buttons
    if (productGrid) {
        productGrid.addEventListener('click', (e) => {
            if (e.target.classList.contains('add-to-cart-btn')) {
                // Prevent navigating if the button is clicked
                e.preventDefault();

                const productId = parseInt(e.target.getAttribute('data-id'));
                const product = products.find(p => p.id === productId);

                if (product) {
                    addToCart(product);
                }
            }
        });
    }

    // Newsletter Submit
    const newsletterForm = document.querySelector('.newsletter-form');
    if (newsletterForm) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const email = document.getElementById('email-input').value;
            if (email) {
                alert(`Thank you for subscribing with ${email}!`);
                newsletterForm.reset();
                announce('Successfully subscribed to newsletter');
            }
        });
    }
}

// Cart Functions
function addToCart(product) {
    cartQuantity++;
    updateCartUI();

    // Accessibility announcement
    announce(`Added ${product.name} to cart. Cart now has ${cartQuantity} items.`);
}

function updateCartUI() {
    if (cartCount) {
        cartCount.textContent = cartQuantity;
        // Update aria-label on the cart button
        const cartBtn = document.querySelector('.cart-btn');
        if (cartBtn) {
            cartBtn.setAttribute('aria-label', `Shopping Cart, ${cartQuantity} items`);
        }
    }
}

// Utility Functions
function setCurrentYear() {
    if (currentYearSpan) {
        currentYearSpan.textContent = new Date().getFullYear();
    }
}

function announce(message) {
    if (announcer) {
        announcer.textContent = message;
        // Clear after a moment so the same message can be announced again if needed
        setTimeout(() => {
            if (announcer.textContent === message) {
                announcer.textContent = '';
            }
        }, 3000);
    }
}

// Run init when DOM is loaded
document.addEventListener('DOMContentLoaded', init);
