+            if (email) {
+                alert(`Thank you for subscribing with ${email}!`);
+                newsletterForm.reset();
+                announce('Successfully subscribed to newsletter');
+            }
+        });
+    }
+}
+
+// Cart Functions
+function addToCart(product) {
